-- name: CreateCryptoTrade :one
INSERT INTO crypto_trade (uuid, crypto_code, crypto_name, description, price, quantity, risk_classification, trade_date, trade_time, trade_type_name, trade_value, transaction_fee_amount, crypto_id, crypto_trade_plan_id, trade_type_id, portfolio_id, created_by, updated_by)
VALUES (sqlc.arg('uuid'),
        (SELECT s.crypto_code FROM crypto s WHERE s.id = sqlc.narg('crypto_id')),
        (SELECT s.crypto_name FROM crypto s WHERE s.id = sqlc.narg('crypto_id')),
        sqlc.narg('description'),
        sqlc.narg('price'),
        sqlc.narg('quantity'),
        sqlc.narg('risk_classification'),
        sqlc.narg('trade_date'),
        sqlc.narg('trade_time'),
        (SELECT s.trade_type_name FROM trade_type s WHERE s.id = sqlc.narg('trade_type_id')),
        round(sqlc.narg('price')::numeric * sqlc.narg('quantity')::numeric, 8),
        sqlc.narg('transaction_fee_amount'),
        sqlc.narg('crypto_id'),
        sqlc.narg('crypto_trade_plan_id'),
        sqlc.narg('trade_type_id'),
        sqlc.narg('portfolio_id'),
        sqlc.arg('actor'),
        sqlc.arg('actor'))
RETURNING uuid;

-- name: UpdateCryptoTrade :execrows
